macro_rules! deps {
    () => {
        IntoParallelRefIterator!();
        IntoParallelRefMutIterator!();
        IntoParallelIterator!();
    };
}

macro_rules! MultiZip {
    () => {
        deps!();
        # [doc = " `MultiZip` is an iterator that zips up a tuple of parallel iterators to"] # [doc = " produce tuples of their items."] # [doc = ""] # [doc = " It is created by calling `into_par_iter()` on a tuple of types that"] # [doc = " implement `IntoParallelIterator`, or `par_iter()`/`par_iter_mut()` with"] # [doc = " types that are iterable by reference."] # [doc = ""] # [doc = " The implementation currently support tuples up to length 12."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = ""] # [doc = " // This will iterate `r` by mutable reference, like `par_iter_mut()`, while"] # [doc = " // ranges are all iterated by value like `into_par_iter()`."] # [doc = " // Note that the zipped iterator is only as long as the shortest input."] # [doc = " let mut r = vec![0; 3];"] # [doc = " (&mut r, 1..10, 10..100, 100..1000).into_par_iter()"] # [doc = "     .for_each(|(r, x, y, z)| *r = x * y + z);"] # [doc = ""] # [doc = " assert_eq!(&r, &[1 * 10 + 100, 2 * 11 + 101, 3 * 12 + 102]);"] # [doc = " ```"] # [doc = ""] # [doc = " For a group that should all be iterated by reference, you can use a tuple reference."] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = ""] # [doc = " let xs: Vec<_> = (1..10).collect();"] # [doc = " let ys: Vec<_> = (10..100).collect();"] # [doc = " let zs: Vec<_> = (100..1000).collect();"] # [doc = ""] # [doc = " // Reference each input separately with `IntoParallelIterator`:"] # [doc = " let r1: Vec<_> = (&xs, &ys, &zs).into_par_iter()"] # [doc = "     .map(|(x, y, z)| x * y + z)"] # [doc = "     .collect();"] # [doc = ""] # [doc = " // Reference them all together with `IntoParallelRefIterator`:"] # [doc = " let r2: Vec<_> = (xs, ys, zs).par_iter()"] # [doc = "     .map(|(x, y, z)| x * y + z)"] # [doc = "     .collect();"] # [doc = ""] # [doc = " assert_eq!(r1, r2);"] # [doc = " ```"] # [doc = ""] # [doc = " Mutable references to a tuple will work similarly."] # [doc = ""] # [doc = " ```"] # [doc = " use rayon::prelude::*;"] # [doc = ""] # [doc = " let mut xs: Vec<_> = (1..4).collect();"] # [doc = " let mut ys: Vec<_> = (-4..-1).collect();"] # [doc = " let mut zs = vec![0; 3];"] # [doc = ""] # [doc = " // Mutably reference each input separately with `IntoParallelIterator`:"] # [doc = " (&mut xs, &mut ys, &mut zs).into_par_iter().for_each(|(x, y, z)| {"] # [doc = "     *z += *x + *y;"] # [doc = "     std::mem::swap(x, y);"] # [doc = " });"] # [doc = ""] # [doc = " assert_eq!(xs, (vec![-4, -3, -2]));"] # [doc = " assert_eq!(ys, (vec![1, 2, 3]));"] # [doc = " assert_eq!(zs, (vec![-3, -1, 1]));"] # [doc = ""] # [doc = " // Mutably reference them all together with `IntoParallelRefMutIterator`:"] # [doc = " let mut tuple = (xs, ys, zs);"] # [doc = " tuple.par_iter_mut().for_each(|(x, y, z)| {"] # [doc = "     *z += *x + *y;"] # [doc = "     std::mem::swap(x, y);"] # [doc = " });"] # [doc = ""] # [doc = " assert_eq!(tuple, (vec![1, 2, 3], vec![-4, -3, -2], vec![-6, -2, 2]));"] # [doc = " ```"] # [derive (Debug , Clone)] pub struct MultiZip < T > { tuple : T , }
    };
}

MultiZip!();